SELECT n.notification_sq, n.notification_type_cd, n.notification_content_txt, n.notification_target_url, n.notification_read_yn, n.notification_created_at_dtm, u.user_nm AS sender_nm FROM tbl_notification_m n LEFT JOIN tbl_user_m u ON n.sender_user_sq = u.user_sq WHERE n.receiver_user_sq = #{receiverUserSq} AND n.notification_is_deleted_yn = 'N'
AND n.notification_type_cd = #{search.notificationTypeCd}
AND n.notification_content_txt LIKE CONCAT('%', #{search.searchKeyword}, '%')
AND n.notification_content_txt LIKE CONCAT('%', #{search.searchKeyword}, '%')
ORDER BY n.notification_created_at_dtm DESC LIMIT #{search.size} OFFSET #{search.offset}

