 UPDATE tbl_notification_m SET
		notification_read_yn = 'Y'
		WHERE notification_sq = #{notificationSq}

 UPDATE tbl_notification_m SET
		notification_is_deleted_yn = 'Y'
		WHERE notification_sq = #{notificationSq}
